{
     "title": "CSCI-352 Operating Systems: Foundations & Core Concepts",
     "learningObjectives": [
       "Define and explain the operational model of a process, including its address space, execution state, and resource ownership.",
       "Describe how system calls and traps transfer control between user mode and privileged kernel mode, and explain the role of page tables in virtual-to- ",
       "Explain how locks and synchronization mechanisms protect shared state invariants during concurrent execution, and identify common deadlock conditions."
     ],
     "beats": [
       {
         "title": "Process Model & State",
         "claim": "A process combines an address space with execution state and operating-system resources.",
         "example": "A running web server process maintains its own stack, heap, and open file descriptors while executing user-level code.",
         "visualDirection": "Show a diagram of a process with labeled components: address space, execution state, and resource ownership. Annotate each component with its function in the OS model.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "System Calls & Privilege Levels",
         "claim": "A system call transfers control from user code to a privileged kernel service.",
         "example": "When a program requests disk I/O, it executes a system call instruction that switches execution to the kernel to handle the request.",
         "visualDirection": "Display a flowchart showing user mode code calling a system call, transitioning to kernel mode, and returning to user mode with a result.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Traps & Processor State",
         "claim": "A trap records processor state so the kernel can handle a system call, exception, or interrupt.",
         "example": "When a page fault occurs, the CPU traps the faulting instruction, saves the instruction pointer and registers, and transfers control to the kernel handler.",
         "visualDirection": "Illustrate a trap sequence with arrows showing state capture, kernel entry, exception handling, and state restoration.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Page Tables & Virtual Memory",
         "claim": "Page tables map virtual addresses to physical memory with permission bits.",
         "example": "A page table entry for a read-only code segment contains a valid bit, a present bit, and a read-only permission flag.",
         "visualDirection": "Show a page table structure with columns for virtual address, physical address, and permission bits, highlighting how mappings are resolved.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Processor Scheduling",
         "claim": "The scheduler selects runnable processes and switches processor context.",
         "example": "The OS scheduler picks a ready process from the run queue, saves the current process's registers, and loads the new process's context.",
         "visualDirection": "Draw a scheduler loop with states: ready queue, running, blocked, and context switch arrows between processes.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Locks & Synchronization",
         "claim": "Locks protect invariants when concurrent execution can access shared state.",
         "example": "A mutex lock ensures that only one thread can modify a shared counter at a time, preventing race conditions.",
         "visualDirection": "Show a lock acquisition/release sequence with two concurrent threads, highlighting mutual exclusion and invariant protection.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Deadlock & Resource Management",
         "claim": "Deadlock occurs when concurrent processes wait for each other's resources, violating resource ownership invariants.",
         "example": "Two processes each hold one file descriptor and wait for the other's, creating a circular dependency that halts progress.",
         "visualDirection": "Illustrate a deadlock scenario with two processes and two resources, showing circular wait arrows and resource ownership.",
         "sourceIds": ["rit-csci-352"]
       },
       {
         "title": "Multiprogramming & Multiprocessing",
         "claim": "Multiprogramming and multiprocessing allow multiple processes to execute concurrently by sharing processor resources.",
         "example": "A server handles multiple client requests simultaneously by switching between processes on a single CPU core.",
         "visualDirection": "Show a CPU core with multiple process contexts interleaved, emphasizing time-sharing and resource allocation.",
         "sourceIds": ["rit-csci-352"]
       },
       {
         "title": "File Systems & I/O",
         "claim": "The file system organizes persistent data through inodes, directories, and logged updates.",
         "example": "A directory entry points to an inode that stores file metadata, permissions, and block addresses for data storage.",
         "visualDirection": "Display a file system tree with directories, inodes, and block clusters, showing how data is organized and updated.",
         "sourceIds": ["mit-xv6-book"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students must verify that user mode, privileged kernel code, hardware translation, interrupt state, resource ownership, and synchronization invariants are correctly implemented.",
         "example": "Audit a kernel module to ensure all shared variables are protected by locks and that page table permissions match access rights.",
         "visualDirection": "Provide a checklist graphic with checkboxes for each invariant: user/kernel mode, hardware translation, interrupt handling, resource ownership, and synchronization.",
         "sourceIds": ["mit-xv6-book", "rit-csci-352"]
       }
     ]
   }
